import React, { useState, useEffect } from 'react';
import Header from '../components/Header';
import MainContent from '../components/MainContent';
import Footer from '../components/Footer';
import MhFooter from '../components/MhFooter';
import MobileFooter from '../components/mobileFooter';
import MobileBanner from '../components/MobileBanner';
import SplashScreen from '../components/SplashScreen';
import GameModal from '../components/GameModal';
import LoadingOverlay from '../components/LoadingOverlay';
import { useSelector } from 'react-redux';

const Home = () => {
    const [showSplash, setShowSplash] = useState(true);
    const { gamePlayed } = useSelector((state) => state.games);
    const { loading } = useSelector((state) => state.load);
    const [isInRange, setIsInRange] = useState(false);
    
    useEffect(() => {
        const setRealHeight = () => {
            const vh = window.innerHeight * 0.01;
            document.documentElement.style.setProperty('--vh', `${vh}px`);
             console.log('RealHeight:', window.innerHeight);
        };

        setRealHeight();
        window.addEventListener('resize', setRealHeight);
        window.addEventListener('orientationchange', setRealHeight);
        
       
        
        return () => {
            window.removeEventListener('resize', setRealHeight);
            window.removeEventListener('orientationchange', setRealHeight);
        };
    }, []);
    
    useEffect(() => {
        const mediaQuery = window.matchMedia(
            '(min-width: 600px) and (max-width: 870px) and (min-height: 501px) and (max-height: 880px)'
        );

        const handleMediaQueryChange = (e) => {
            console.log("hell")
            setIsInRange(e.matches);
        };

        mediaQuery.addEventListener('change', handleMediaQueryChange);
        handleMediaQueryChange(mediaQuery);

        return () => mediaQuery.removeEventListener('change', handleMediaQueryChange);
    }, []);
    
    return (
        <>
            {gamePlayed ? (
                <GameModal />
            ) :
                (<div className='relative flex flex-col w-full h-screen md:h-screen android:h-screen'
                    style={!isInRange ? {
                        height: 'calc(var(--vh, 1vh) * 100)'
                    } : {}}
                >
                    {loading && <LoadingOverlay />}
                    {showSplash && <SplashScreen onFinish={() => setShowSplash(false)} />}
                    <Header />
                    <MobileBanner />
                    
                    <MainContent />
                    <Footer />
                    <MobileFooter />
                    <MhFooter />
                </div >)
            }
        </>
    );
}

export default Home;
